export const LESSONS = [...PRIMARY_LESSONS, ...SECONDARY_LESSONS, ...PROGRAMMING_LESSONS, ...STORY_LESSONS];

export const LESSONS_BY_GRADE = (gradeId) => LESSONS.filter((l) => l.gradeId === gradeId);
export const LESSONS_BY_SUBJECT = (gradeId, subject) =>
  LESSONS.filter((l) => l.gradeId === gradeId && l.subject === subject);
export const getLesson = (id) => LESSONS.find((l) => l.id === id);
export const getGrade = (id) => GRADES.find((g) => g.id === id);
